package com.groupvm.catalog.resource;
import com.groupvm.catalog.application.ProductService; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@WebMvcTest(ProductResource.class) class ProductResourceTest { @Autowired MockMvc mvc; @MockBean ProductService service; @Test void rejectsInvalidCreateRequest() throws Exception {mvc.perform(post("/api/v1/products").contentType(MediaType.APPLICATION_JSON).content("{\"sku\":\"\",\"name\":\"\",\"price\":0}")).andExpect(status().isBadRequest());verifyNoInteractions(service);} }
